import os
from mindee import Client, product

def validate_invoice_fields(invoice_path: str) -> dict:
<GAP>
    mindee_client = Client(api_key=os.environ.get("MINDEE_API_KEY"))
    input_doc = mindee_client.doc_from_path(invoice_path)
    result = mindee_client.parse(input_doc, product.InvoiceV4)

    required_fields = {
        "invoice_number": result.document.inference.prediction.invoice_number,
        "total_amount": result.document.inference.prediction.total_amount,
        "date": result.document.inference.prediction.date,
        "supplier_name": result.document.inference.prediction.supplier_name,
    }

    validation_results = {}
    for field_name, field_object in required_fields.items():
        is_present = field_object is not None and field_object.value is not None
        confidence = field_object.confidence if is_present else 0.0

        validation_results[field_name] = {
            "is_present": is_present,
            "confidence": confidence,
            "value": field_object.value if is_present else None
        }

    return validation_results
